28	constexpr int32_t SPLIT_MODE_C = 1;
29	constexpr int32_t SPLIT_MODE_W = 2;
30	constexpr int32_t SPLIT_MODE_MULTI_W = 3;
31	
32	constexpr int32_t IMPL_GENERIC = 0;
33	constexpr int32_t IMPL_REDUCE_D = 1;
34	constexpr int32_t IMPL_SPLIT_C = 2;
35	constexpr int32_t IMPL_SPLIT_W = 3;
