177	    tiling->kD = kd32;         tiling->kH = kh32;         tiling->kW = kw32;
178	    tiling->sD = sd32;         tiling->sH = sh32;         tiling->sW = sw32;
179	    tiling->pD = pd32;         tiling->pH = ph32;         tiling->pW = pw32;
180	    tiling->countIncludePad = countIncludePad;
181	    tiling->divisorOverride = divisorOverride;
182	    tiling->splitMode = splitMode;
183	    tiling->blockC = blockC;
184	    tiling->splitWTileKw = splitWTileKw;
185	    tiling->multiWWindow = multiWWindow;
186	    tiling->blockM = blockM;   tiling->subBlockM = subBlockM;
187	    tiling->mNum = mNum;       tiling->outSpatial = outSpatial;
188	    tiling->inSpatial = inSpatial;
189	    tiling->hw = h32 * w32;    tiling->cNum = 1;
190	    tiling->usedCoreNum = usedCoreNum;
191	    tiling->tasksPerCore = tasksPerCore;
192	    tiling->vectorLen = vectorLen;
193	    tiling->reserved0 = implMode;
194	    tiling->reserved1 = 0;
195	}
