197	static inline void LaunchAvgPool3dKernel(
198	    int32_t implMode, uint32_t blockDim,
199	    const at::Tensor &x_flat, at::Tensor &y_flat, const at::Tensor &tilingNpu)
200	{
201	    switch (implMode) {
202	        case IMPL_REDUCE_D:
203	            EXEC_KERNEL_CMD(avg_pool3_d_reduce_d, blockDim, x_flat, y_flat, tilingNpu); break;
204	        case IMPL_SPLIT_C:
205	            EXEC_KERNEL_CMD(avg_pool3_d_split_c, blockDim, x_flat, y_flat, tilingNpu); break;
206	        case IMPL_SPLIT_W:
207	            EXEC_KERNEL_CMD(avg_pool3_d_split_w, blockDim, x_flat, y_flat, tilingNpu); break;
208	        case IMPL_MULTI_W:
209	            EXEC_KERNEL_CMD(avg_pool3_d_multi_w, blockDim, x_flat, y_flat, tilingNpu); break;
210	        case IMPL_GENERIC:
211	        default:
212	            EXEC_KERNEL_CMD(avg_pool3_d_generic, blockDim, x_flat, y_flat, tilingNpu); break;
213	    }
214	}
