222	static inline AvgPool3dI32Params MakeAvgPool3dI32Params(
223	    int64_t n, int64_t c, int64_t d, int64_t h, int64_t w,
224	    int64_t o_d, int64_t o_h, int64_t o_w,
225	    int64_t k_d, int64_t k_h, int64_t k_w,
226	    int64_t s_d, int64_t s_h, int64_t s_w,
227	    int64_t p_d, int64_t p_h, int64_t p_w,
228	    bool count_include_pad, c10::optional<int64_t> divisor_override)
229	{
230	    AvgPool3dI32Params p;
231	    p.n = static_cast<int32_t>(n); p.c = static_cast<int32_t>(c);
232	    p.d = static_cast<int32_t>(d); p.h = static_cast<int32_t>(h);
233	    p.w = static_cast<int32_t>(w);
234	    p.od = static_cast<int32_t>(o_d); p.oh = static_cast<int32_t>(o_h);
235	    p.ow = static_cast<int32_t>(o_w);
236	    p.kd = static_cast<int32_t>(k_d); p.kh = static_cast<int32_t>(k_h);
237	    p.kw = static_cast<int32_t>(k_w);
238	    p.sd = static_cast<int32_t>(s_d); p.sh = static_cast<int32_t>(s_h);
239	    p.sw = static_cast<int32_t>(s_w);
240	    p.pd = static_cast<int32_t>(p_d); p.ph = static_cast<int32_t>(p_h);
241	    p.pw = static_cast<int32_t>(p_w);
242	    p.cntPad = count_include_pad ? 1 : 0;
243	    p.divOverride = divisor_override.has_value()
244	        ? static_cast<int32_t>(divisor_override.value()) : 0;
245	    return p;
246	}
247	
248	static inline at::Tensor PrepareAndLaunchAvgPool3d(
249	    const at::Tensor &self, bool is_5d,
250	    int64_t n, int64_t c, int64_t d, int64_t h, int64_t w,
251	    int64_t o_d, int64_t o_h, int64_t o_w,
252	    int64_t k_d, int64_t k_h, int64_t k_w,
253	    int64_t s_d, int64_t s_h, int64_t s_w,
254	    int64_t p_d, int64_t p_h, int64_t p_w,
255	    bool count_include_pad, c10::optional<int64_t> divisor_override)
256	{
257	    auto ap = MakeAvgPool3dI32Params(
258	        n, c, d, h, w, o_d, o_h, o_w, k_d, k_h, k_w,
259	        s_d, s_h, s_w, p_d, p_h, p_w, count_include_pad, divisor_override);
260	
261	    at::Tensor x_input = is_5d ? self.permute({0, 2, 3, 4, 1}).contiguous()
262	                               : self.permute({0, 2, 3, 1}).contiguous();
263	    at::Tensor x_flat = x_input.reshape({n * d * h * w, c});
264	    TORCH_CHECK(x_flat.is_contiguous(), "avg_pool3d: x_flat must be contiguous");
265	    TORCH_CHECK(x_flat.scalar_type() == at::kFloat, "avg_pool3d: only float32 is supported");
266	
267	    int32_t inSpatial = ap.d * ap.h * ap.w;
268	    int32_t outSpatial = ap.od * ap.oh * ap.ow;
269	    int32_t mOut = ap.n * outSpatial;
270	    int32_t blockM = ChooseBlockM(mOut);
271	    if (blockM == 0) { blockM = 1; }
272	    int32_t subBlockM = blockM / DEFAULT_VEC_NUM;
273	    int32_t mNum = mOut / blockM;
274	    int32_t usedCoreNum = std::min(DEFAULT_NUM_PHYSICAL_CORES, mNum);
275	    int32_t tasksPerCore = CeilDivI32(mNum, usedCoreNum);
276	    int32_t implMode = ResolveImplMode(0, ap.kh, ap.kw, ap.sh, ap.sw, ap.ph, ap.pw, ap.c);
277	
278	    at::Tensor y_flat = at::empty({mOut, ap.c}, at::device(at::kPrivateUse1).dtype(at::kFloat));
279	    at::Tensor tilingCpu = at::empty({static_cast<long>(sizeof(AvgPool3DKernelTiling))},
280	                                      at::device(at::kCPU).dtype(at::kByte));
281	    auto *tiling = reinterpret_cast<AvgPool3DKernelTiling *>(tilingCpu.data_ptr());
282	
283	    PopulateAvgPool3dTiling(tiling,
284	        ap.n, ap.c, ap.d, ap.h, ap.w, ap.od, ap.oh, ap.ow,
285	        ap.kd, ap.kh, ap.kw, ap.sd, ap.sh, ap.sw, ap.pd, ap.ph, ap.pw,
286	        ap.cntPad, ap.divOverride,
287	        0, 0, 0, 1, blockM, subBlockM, mNum, outSpatial, inSpatial,
288	        usedCoreNum, tasksPerCore, std::min<int32_t>(ap.c, 256), implMode);
289	
290	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
291	    tiling->launchBlocks = static_cast<int32_t>(blockDim);
292	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
293	
294	    LaunchAvgPool3dKernel(implMode, blockDim, x_flat, y_flat, tilingNpu);
295	    return y_flat;
296	}
297	
298	at::Tensor avg_pool3d(const at::Tensor &self, at::IntArrayRef kernel_size, at::IntArrayRef stride,
299	                      at::IntArrayRef padding, bool ceil_mode, bool count_include_pad,
300	                      c10::optional<int64_t> divisor_override)
301	{
302	    TORCH_CHECK(self.dim() == 4 || self.dim() == 5, "avg_pool3d: input must be 4D or 5D");
303	    TORCH_CHECK(!kernel_size.empty(), "avg_pool3d: kernel_size must not be empty");
304	
305	    auto params = NormalizePool3dParams(kernel_size, stride, padding);
306	    int64_t k_d = params.k_d, k_h = params.k_h, k_w = params.k_w;
307	    int64_t s_d = params.s_d, s_h = params.s_h, s_w = params.s_w;
308	    int64_t p_d = params.p_d, p_h = params.p_h, p_w = params.p_w;
309	
310	    TORCH_CHECK(s_d != 0 && s_h != 0 && s_w != 0, "avg_pool3d: stride should not contain zero");
311	
312	    c10::SmallVector<int64_t, 3> kernel_sizes = {k_d, k_h, k_w};
313	    c10::SmallVector<int64_t, 3> stride_sizes = {s_d, s_h, s_w};
314	    c10::SmallVector<int64_t, 3> padding_sizes = {p_d, p_h, p_w};
315	
316	    auto output_size = avg_pool3d_output_size(self, at::IntArrayRef(kernel_sizes),
317	                                               at::IntArrayRef(stride_sizes),
318	                                               at::IntArrayRef(padding_sizes), ceil_mode);
319	    at::Tensor result = at_npu::native::empty_with_format(
320	        output_size, self.options(), at_npu::native::get_npu_format(self));
321	
322	    int64_t n = self.size(0);
323	    bool is_5d = (self.dim() == 5);
324	    int64_t c = is_5d ? self.size(1) : 1;
325	    int64_t d = self.size(-3), h = self.size(-2), w = self.size(-1);
326	    int64_t dim_offset = is_5d ? 1 : 0;
327	    int64_t o_d = output_size[1 + dim_offset];
328	    int64_t o_h = output_size[2 + dim_offset];
329	    int64_t o_w = output_size[3 + dim_offset];
330	
331	    at::Tensor y_flat = PrepareAndLaunchAvgPool3d(
332	        self, is_5d, n, c, d, h, w, o_d, o_h, o_w,
333	        k_d, k_h, k_w, s_d, s_h, s_w, p_d, p_h, p_w,
334	        count_include_pad, divisor_override);
335	
336	    at::Tensor y_ndhwc = y_flat.reshape({n, o_d, o_h, o_w, c});
337	    at::Tensor y_ncdhw = y_ndhwc.permute({0, 4, 1, 2, 3}).contiguous();
338	    if (self.dim() == 4) {
339	        y_ncdhw = y_ncdhw.squeeze(1).contiguous();
340	    }
341	    if (!y_ncdhw.is_same(result)) {
342	        result.copy_(y_ncdhw);
343	    }
344	    return result;
345	}
