26	template <typename T>
27	__aicore__ inline void CopyTiling(T *tiling, GM_ADDR tilingGM)
28	{
29	    int32_t *dst = reinterpret_cast<int32_t *>(tiling);
30	    auto *src = reinterpret_cast<__gm__ int32_t *>(tilingGM);
31	    for (size_t i = 0; i < sizeof(T) / sizeof(int32_t); ++i) {
32	        dst[i] = src[i];
33	    }
34	}
