71	// Shared worker-loop helper — replaces the identical Process() body in AvgPool3DSplitCKernel
72	// and AvgPool3DSplitWKernel (see "duplicate code" notes in those files).
73	template <typename F>
74	__aicore__ inline void AvgPool3DProcessLoop(F &&processRowFn, int launchBlocks, int N, int outSpatial)
75	{
76	    if ASCEND_IS_AIV {
77	        const int workerId = static_cast<int>(AscendC::GetBlockIdx());
78	        int workerCount = launchBlocks;
79	        if (workerCount <= 0) {
80	            workerCount = 1;
81	        }
82	        const int totalRows = N * outSpatial;
83	        for (int outRow = workerId; outRow < totalRows; outRow += workerCount) {
84	            processRowFn(outRow);
85	        }
86	    }
87	}
88	
89	// Shared output-store helper — replaces the identical accumulator-to-GM output section in
90	// AvgPool3DSplitCKernel::ProcessOneRowChunk and AvgPool3DSplitWKernel::ProcessOneRowChunk.
91	__aicore__ inline void AvgPool3DStoreOutput(
92	    AscendC::TQue<AscendC::TPosition::VECOUT, 0> &outQueue,
93	    AscendC::LocalTensor<float> &outLocal,
94	    AscendC::LocalTensor<float> &accLocal,
95	    const AscendC::GlobalTensor<float> &yGM,
96	    int outRow, int cBase, int cLen,
97	    int od, int oh, int ow,
98	    const AvgPool3DKernelTiling &tiling)
99	{
100	    outQueue.AllocTensor<float>(outLocal);
101	    const int divisor = ComputeDivisorHelper(od, oh, ow, tiling);
102	    if (divisor <= 0) {
103	        AscendC::Duplicate(outLocal, 0.0f, cLen);
104	    } else {
105	        const float invDiv = 1.0f / static_cast<float>(divisor);
106	        AscendC::Muls(outLocal, accLocal, invDiv, cLen);
107	    }
108	    outQueue.EnQue(outLocal);
109	    outQueue.DeQue<float>(outLocal);
110	    AscendC::DataCopy(yGM[static_cast<uint64_t>(outRow) * tiling.C + cBase], outLocal, cLen);
111	    outQueue.FreeTensor(outLocal);
112	}
