11	// AscendC SwiGLU kernel
12	// SwiGLU(x, dim) = SiLU(a) * b, where a, b = chunk(x, 2, dim=sliced_dim)
13	// This kernel assumes chunk dim is innermost (-1).
14	// Supports float32, float16, bfloat16.
15	
16	#include "kernel_operator.h"
17	
18	constexpr int32_t BUFFER_NUM = 1;
19	constexpr int32_t TILE_SIZE = 1024;
20	
21	// ---------------------------------------------------------------------------
22	// Inline helpers
23	// ---------------------------------------------------------------------------
24	
25	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
26	{
27	    if (b == 0U) { return 0U; }
28	    return (a + b - 1U) / b;
29	}
30	
31	template <typename T>
32	__aicore__ inline void LoadGmToUb(
33	    AscendC::LocalTensor<T> &dst,
34	    AscendC::GlobalTensor<T> src,
35	    uint32_t count)
36	{
37	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
38	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
39	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
40	}
41	
42	template <typename T>
43	__aicore__ inline void StoreUbToGm(
44	    AscendC::GlobalTensor<T> dst,
45	    const AscendC::LocalTensor<T> &src,
46	    uint32_t count)
47	{
48	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
49	    AscendC::DataCopyPad(dst, src, copyParams);
50	}
