53	// Cast / prepare helpers
54	// ---------------------------------------------------------------------------
55	
56	template <typename dataType>
57	__aicore__ inline void PrepareInput(
58	    AscendC::LocalTensor<float> &dst,
59	    AscendC::LocalTensor<dataType> &src,
60	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
61	    int32_t count)
62	{
63	    if constexpr (std::is_same_v<dataType, float>) {
64	        dst = src.template ReinterpretCast<float>();
65	        AscendC::PipeBarrier<PIPE_ALL>();
66	    } else {
67	        dst = castBuf.Get<float>();
68	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
69	        AscendC::PipeBarrier<PIPE_V>();
70	    }
71	}
72	
73	template <typename dataType>
74	__aicore__ inline void PrepareOutput(
75	    AscendC::LocalTensor<float> &dst,
76	    AscendC::LocalTensor<dataType> &out,
77	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
78	{
79	    if constexpr (std::is_same_v<dataType, float>) {
80	        dst = out.template ReinterpretCast<float>();
81	    } else {
82	        dst = castBuf.Get<float>();
83	    }
84	}
85	
86	template <typename dataType>
87	__aicore__ inline AscendC::RoundMode OutputRoundMode()
88	{
89	    if constexpr (std::is_same_v<dataType, bfloat16_t>) {
90	        return AscendC::RoundMode::CAST_ROUND;
91	    }
92	    return AscendC::RoundMode::CAST_NONE;
93	}
94	
95	template <typename dataType>
96	__aicore__ inline void FinalizeOutput(
97	    AscendC::LocalTensor<dataType> &out,
98	    AscendC::LocalTensor<float> &src,
99	    int32_t count)
100	{
101	    if constexpr (!std::is_same_v<dataType, float>) {
102	        AscendC::Cast(out, src, OutputRoundMode<dataType>(), count);
103	        AscendC::PipeBarrier<PIPE_V>();
104	    } else {
105	        AscendC::PipeBarrier<PIPE_V>();
106	    }
107	}
108	
109	// =========================================================================
110	// SwiGLU Kernel
111	// =========================================================================
112	
113	template <typename dataType>
114	class SwiGLUKernel {
115	public:
116	    __aicore__ inline void Init(
117	        GM_ADDR x, GM_ADDR y,
118	        int32_t outerSize, int32_t D, int32_t halfD,
119	        int32_t usedCoreNum, int32_t tasksPerCore)
120	    {
121	        this->outerSize = outerSize;
122	        this->D = D;
123	        this->halfD = halfD;
124	        this->usedCoreNum = usedCoreNum;
125	        this->tasksPerCore = tasksPerCore;
126	        this->tileSize = TILE_SIZE;
127	        if (halfD < tileSize) {
128	            this->tileSize = halfD;
129	        }
130	
131	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
132	                             static_cast<uint64_t>(outerSize) * D);
133	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y),
134	                             static_cast<uint64_t>(outerSize) * halfD);
135	
136	        if ASCEND_IS_AIV {
137	            pipe.InitBuffer(aInQueue_, BUFFER_NUM, tileSize * sizeof(dataType));
138	            pipe.InitBuffer(bInQueue_, BUFFER_NUM, tileSize * sizeof(dataType));
139	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileSize * sizeof(dataType));
140	            pipe.InitBuffer(aBuf_, tileSize * sizeof(float));
141	            pipe.InitBuffer(bBuf_, tileSize * sizeof(float));
142	            pipe.InitBuffer(t0Buf_, tileSize * sizeof(float));
143	            pipe.InitBuffer(t1Buf_, tileSize * sizeof(float));
144	            if constexpr (!std::is_same_v<dataType, float>) {
145	                pipe.InitBuffer(aCastBuf_, tileSize * sizeof(float));
146	                pipe.InitBuffer(bCastBuf_, tileSize * sizeof(float));
147	                pipe.InitBuffer(yCastBuf_, tileSize * sizeof(float));
148	            }
149	        }
150	    }
151	
152	    __aicore__ inline void Process()
153	    {
154	        if ASCEND_IS_AIV {
155	            const int coreIdx = AscendC::GetBlockIdx();
156	            const int subBlockNum = AscendC::GetSubBlockNum();
157	
158	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
159	                const int bx = coreIdx * tasksPerCore + localIdx;
160	                for (int r = 0; r < subBlockNum; ++r) {
161	                    const int rowIdx = bx * subBlockNum + r;
162	                    if (rowIdx >= outerSize) { continue; }
163	                    ProcessRow(rowIdx);
164	                }
165	            }
166	        }
167	    }
168	
169	private:
170	    __aicore__ inline void CopyInTiles(int32_t rowIdx, int32_t colStart, int32_t curLen)
171	    {
172	        aInLocal_ = aInQueue_.AllocTensor<dataType>();
173	        LoadGmToUb(aInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * D + colStart],
174	                   static_cast<uint32_t>(curLen));
175	        aInQueue_.EnQue(aInLocal_);
176	
177	        bInLocal_ = bInQueue_.AllocTensor<dataType>();
178	        LoadGmToUb(bInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * D + halfD + colStart],
179	                   static_cast<uint32_t>(curLen));
180	        bInQueue_.EnQue(bInLocal_);
181	    }
182	
183	    __aicore__ inline void ComputeSwiGLU(int32_t curLen)
184	    {
185	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
186	        PrepareOutput<dataType>(yLocal_, yOutLocal_, yCastBuf_);
187	
188	        aInLocal_ = aInQueue_.DeQue<dataType>();
189	        bInLocal_ = bInQueue_.DeQue<dataType>();
190	        PrepareInput<dataType>(aLocal_, aInLocal_, aCastBuf_, curLen);
191	        PrepareInput<dataType>(bLocal_, bInLocal_, bCastBuf_, curLen);
192	
193	        t0Local_ = t0Buf_.Get<float>();
194	        t1Local_ = t1Buf_.Get<float>();
195	
196	        // Step 1: t1 = sigmoid(a)  (native AscendC Sigmoid API)
197	        AscendC::Sigmoid(t1Local_, aLocal_, curLen);
198	
199	        // Step 2: t0 = a * sigmoid(a) = SiLU(a)
200	        AscendC::Mul(t0Local_, aLocal_, t1Local_, curLen);
201	
202	        // Step 3: y = SiLU(a) * b = SwiGLU output
203	        AscendC::Mul(yLocal_, t0Local_, bLocal_, curLen);
204	
205	        FinalizeOutput<dataType>(yOutLocal_, yLocal_, curLen);
206	
207	        aInQueue_.FreeTensor(aInLocal_);
208	        bInQueue_.FreeTensor(bInLocal_);
209	        yOutQueue_.EnQue(yOutLocal_);
210	    }
211	
212	    __aicore__ inline void CopyOutTile(int32_t rowIdx, int32_t colStart, int32_t curLen)
213	    {
214	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
215	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * halfD + colStart],
216	                    yOutLocal_, static_cast<uint32_t>(curLen));
217	        yOutQueue_.FreeTensor(yOutLocal_);
218	    }
219	
220	    __aicore__ inline void ProcessTile(int32_t rowIdx, int32_t colStart, int32_t curLen)
221	    {
222	        CopyInTiles(rowIdx, colStart, curLen);
223	        ComputeSwiGLU(curLen);
224	        CopyOutTile(rowIdx, colStart, curLen);
225	    }
226	
227	    __aicore__ inline void ProcessRow(int32_t rowIdx)
228	    {
229	        int32_t tilesPerRow = static_cast<int32_t>(
230	            CeilDivU32(static_cast<uint32_t>(halfD), static_cast<uint32_t>(tileSize)));
231	
232	        for (int32_t ti = 0; ti < tilesPerRow; ++ti) {
233	            int32_t colStart = ti * tileSize;
234	            int32_t curLen = (colStart + tileSize <= halfD) ? tileSize : (halfD - colStart);
235	            ProcessTile(rowIdx, colStart, curLen);
236	        }
237	    }
238	
239	private:
240	    int32_t outerSize = 0;
241	    int32_t D = 0;
242	    int32_t halfD = 0;
243	    int32_t usedCoreNum = 0;
244	    int32_t tasksPerCore = 0;
245	    int32_t tileSize = 0;
246	
247	    AscendC::TPipe pipe;
248	    AscendC::GlobalTensor<dataType> xGM_;
249	    AscendC::GlobalTensor<dataType> yGM_;
250	
251	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> aInQueue_;
252	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> bInQueue_;
253	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
254	
255	    AscendC::TBuf<AscendC::TPosition::VECCALC> aBuf_;
256	    AscendC::TBuf<AscendC::TPosition::VECCALC> bBuf_;
257	    AscendC::TBuf<AscendC::TPosition::VECCALC> t0Buf_;
258	    AscendC::TBuf<AscendC::TPosition::VECCALC> t1Buf_;
259	
260	    AscendC::TBuf<AscendC::TPosition::VECCALC> aCastBuf_;
261	    AscendC::TBuf<AscendC::TPosition::VECCALC> bCastBuf_;
262	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
263	
264	    AscendC::LocalTensor<dataType> aInLocal_;
265	    AscendC::LocalTensor<dataType> bInLocal_;
266	    AscendC::LocalTensor<dataType> yOutLocal_;
267	    AscendC::LocalTensor<float> aLocal_;
268	    AscendC::LocalTensor<float> bLocal_;
269	    AscendC::LocalTensor<float> yLocal_;
270	    AscendC::LocalTensor<float> t0Local_;
271	    AscendC::LocalTensor<float> t1Local_;
272	};
273	
274	// =========================================================================
275	// Kernel entry point — dtype dispatch: 0=fp32, 1=fp16, 2=bf16
276	// =========================================================================
277	
278	extern "C" __global__ __aicore__ void swiglu(
279	    GM_ADDR x, GM_ADDR y,
280	    int32_t outerSize, int32_t D, int32_t halfD,
281	    int32_t usedCoreNum, int32_t tasksPerCore,
282	    int64_t dtypeFlag)
283	{
284	    if (dtypeFlag == 0) {
285	        SwiGLUKernel<float> kernel;
286	        kernel.Init(x, y, outerSize, D, halfD, usedCoreNum, tasksPerCore);
287	        kernel.Process();
288	    } else if (dtypeFlag == 1) {
289	        SwiGLUKernel<half> kernel;
290	        kernel.Init(x, y, outerSize, D, halfD, usedCoreNum, tasksPerCore);
291	        kernel.Process();
292	    } else {
293	        SwiGLUKernel<bfloat16_t> kernel;
294	        kernel.Init(x, y, outerSize, D, halfD, usedCoreNum, tasksPerCore);
295	        kernel.Process();
296	    }
297	}
