39	    int32_t D = static_cast<int32_t>(x.size(1));
40	    TORCH_CHECK(D % 2 == 0, "Chunk dimension D must be even");
41	    int32_t halfD = D / 2;
42	
43	    int32_t totalRows = outerSize;
44	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,
45	                                            std::max<int32_t>(1, totalRows));
46	    int32_t tasksPerCore = (totalRows + usedCoreNum - 1) / usedCoreNum;
47	
48	    // Allocate output
49	    at::Tensor y = at::empty({outerSize, halfD}, x.options());
50	
51	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
52	    int64_t dtypeFlag = 0;
