// AscendC AvgPool3d kernel
// Operates on flattened NDHWC layout: (N*D*H*W, C) -> (N*D_out*H_out*W_out, C)
// Supports float32, float16, bfloat16.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t DEFAULT_VEC_LEN = 256;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

// ---------------------------------------------------------------------------
// Tiling data passed from host via GM
// ---------------------------------------------------------------------------
struct AvgPool3dTiling {
    int32_t N;           int32_t C;
    int32_t D;           int32_t H;           int32_t W;
    int32_t OD;          int32_t OH;          int32_t OW;
    int32_t kD;          int32_t kH;          int32_t kW;
    int32_t sD;          int32_t sH;          int32_t sW;
    int32_t pD;          int32_t pH;          int32_t pW;
    int32_t countIncludePad;
    int32_t divisorOverride;
    int32_t inSpatial;
    int32_t outSpatial;
    int32_t hw;          // H * W
    int32_t vecLen;
    int32_t launchBlocks;
    int32_t reserved[8];
};

__aicore__ inline void CopyTiling(AvgPool3dTiling *tiling, GM_ADDR tilingGM)
{
    int32_t *dst = reinterpret_cast<int32_t *>(tiling);
    auto *src = reinterpret_cast<__gm__ int32_t *>(tilingGM);
    constexpr size_t count = sizeof(AvgPool3dTiling) / sizeof(int32_t);
    for (size_t i = 0; i < count; ++i) {
        dst[i] = src[i];
    }
}

// ---------------------------------------------------------------------------
// Cast / prepare helpers
// ---------------------------------------------------------------------------
template <typename dataType>
__aicore__ inline void PrepareInputF32(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<dataType> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<dataType, float>) {
        dst = src.template ReinterpretCast<float>();
        AscendC::PipeBarrier<PIPE_ALL>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename dataType>
__aicore__ inline AscendC::RoundMode OutputRoundMode()
{
    if constexpr (std::is_same_v<dataType, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename dataType>
__aicore__ inline void CastBack(
    AscendC::LocalTensor<dataType> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<dataType, float>) {
        AscendC::Cast(out, src, OutputRoundMode<dataType>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// ---------------------------------------------------------------------------
// AvgPool3d Kernel
// ---------------------------------------------------------------------------
template <typename dataType>
class AvgPool3dKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM,
                                 AscendC::TPipe *pipe)
    {
        CopyTiling(&tiling_, tilingGM);
        if (tiling_.vecLen <= 0) { tiling_.vecLen = DEFAULT_VEC_LEN; }
        if (tiling_.vecLen > tiling_.C) { tiling_.vecLen = tiling_.C; }

        uint64_t inElemNum = static_cast<uint64_t>(tiling_.N) * tiling_.inSpatial * tiling_.C;
        uint64_t outElemNum = static_cast<uint64_t>(tiling_.N) * tiling_.outSpatial * tiling_.C;
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), inElemNum);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), outElemNum);

        if ASCEND_IS_AIV {
            pipe_ = pipe;
            vecLen_ = tiling_.vecLen;
            pipe_->InitBuffer(inQueue_, BUFFER_NUM, static_cast<uint32_t>(vecLen_ * sizeof(dataType)));
            pipe_->InitBuffer(outQueue_, BUFFER_NUM, static_cast<uint32_t>(vecLen_ * sizeof(dataType)));
            pipe_->InitBuffer(accBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe_->InitBuffer(castInBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
                pipe_->InitBuffer(castOutBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int workerId = static_cast<int>(AscendC::GetBlockIdx());
            int workerCount = tiling_.launchBlocks;
            if (workerCount <= 0) { workerCount = 1; }
            int totalRows = tiling_.N * tiling_.outSpatial;

            for (int outRow = workerId; outRow < totalRows; outRow += workerCount) {
                ProcessOneRow(outRow);
            }
        }
    }

private:
    __aicore__ inline int ComputeDivisor(int od, int oh, int ow) const
    {
        if (tiling_.divisorOverride > 0) {
            return tiling_.divisorOverride;
        }
        if (tiling_.countIncludePad > 0) {
            return tiling_.kD * tiling_.kH * tiling_.kW;
        }
        int dStart = od * tiling_.sD - tiling_.pD;
        int hStart = oh * tiling_.sH - tiling_.pH;
        int wStart = ow * tiling_.sW - tiling_.pW;
        int dBegin = dStart < 0 ? 0 : dStart;
        int hBegin = hStart < 0 ? 0 : hStart;
        int wBegin = wStart < 0 ? 0 : wStart;
        int dEnd = dStart + tiling_.kD > tiling_.D ? tiling_.D : dStart + tiling_.kD;
        int hEnd = hStart + tiling_.kH > tiling_.H ? tiling_.H : hStart + tiling_.kH;
        int wEnd = wStart + tiling_.kW > tiling_.W ? tiling_.W : wStart + tiling_.kW;
        int validD = dEnd > dBegin ? (dEnd - dBegin) : 0;
        int validH = hEnd > hBegin ? (hEnd - hBegin) : 0;
        int validW = wEnd > wBegin ? (wEnd - wBegin) : 0;
        return validD * validH * validW;
    }

    __aicore__ inline void ProcessCTile(int outRow, int cBase, int cLen,
                                         int nIdx, int od, int oh, int ow)
    {
        // Accumulate input over kernel window
        accLocal_ = accBuf_.Get<float>();
        AscendC::Duplicate(accLocal_, 0.0f, cLen);

        for (int kd = 0; kd < tiling_.kD; ++kd) {
            int idVal = od * tiling_.sD - tiling_.pD + kd;
            if (idVal < 0 || idVal >= tiling_.D) { continue; }
            for (int kh = 0; kh < tiling_.kH; ++kh) {
                int ihVal = oh * tiling_.sH - tiling_.pH + kh;
                if (ihVal < 0 || ihVal >= tiling_.H) { continue; }
                for (int kw = 0; kw < tiling_.kW; ++kw) {
                    int iwVal = ow * tiling_.sW - tiling_.pW + kw;
                    if (iwVal < 0 || iwVal >= tiling_.W) { continue; }
                    int inRow = nIdx * tiling_.inSpatial + idVal * tiling_.hw +
                                ihVal * tiling_.W + iwVal;

                    // CopyIn: load input slice
                    inLocal_ = inQueue_.AllocTensor<dataType>();
                    AscendC::DataCopyPadParams padParams{true, 0, 0, static_cast<dataType>(0)};
                    AscendC::DataCopyPad(inLocal_,
                        xGM_[static_cast<uint64_t>(inRow) * tiling_.C + cBase],
                        {1, static_cast<uint32_t>(cLen) * sizeof(dataType), 0, 0},
                        padParams);
                    inQueue_.EnQue(inLocal_);

                    // DeQue and accumulate
                    inLocal_ = inQueue_.DeQue<dataType>();
                    PrepareInputF32<dataType>(inFloatLocal_, inLocal_, castInBuf_, cLen);
                    AscendC::Add(accLocal_, accLocal_, inFloatLocal_, cLen);
                    inQueue_.FreeTensor(inLocal_);
                }
            }
        }

        // Compute output: acc / divisor
        int divisor = ComputeDivisor(od, oh, ow);
        outLocal_ = outQueue_.AllocTensor<dataType>();

        if (divisor <= 0) {
            // Zero out if divisor is 0
            if constexpr (std::is_same_v<dataType, float>) {
                outFloatLocal_ = outLocal_.template ReinterpretCast<float>();
                AscendC::Duplicate(outFloatLocal_, 0.0f, cLen);
                AscendC::PipeBarrier<PIPE_V>();
            } else {
                float *outFloatRaw = castOutBuf_.Get<float>();
                AscendC::Duplicate(outFloatRaw, 0.0f, cLen);
                CastBack<dataType>(outLocal_, outFloatRaw, cLen);
            }
        } else {
            float invDiv = 1.0f / static_cast<float>(divisor);
            if constexpr (std::is_same_v<dataType, float>) {
                outFloatLocal_ = outLocal_.template ReinterpretCast<float>();
                AscendC::Muls(outFloatLocal_, accLocal_, invDiv, cLen);
                AscendC::PipeBarrier<PIPE_V>();
            } else {
                float *outFloatRaw = castOutBuf_.Get<float>();
                AscendC::Muls(outFloatRaw, accLocal_, invDiv, cLen);
                CastBack<dataType>(outLocal_, outFloatRaw, cLen);
            }
        }

        outQueue_.EnQue(outLocal_);

        // CopyOut
        outLocal_ = outQueue_.DeQue<dataType>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(cLen) * sizeof(dataType), 0, 0, 0};
        AscendC::DataCopyPad(yGM_[static_cast<uint64_t>(outRow) * tiling_.C + cBase],
                             outLocal_, copyParams);
        outQueue_.FreeTensor(outLocal_);
    }

    __aicore__ inline void ProcessOneRow(int outRow)
    {
        int nIdx = outRow / tiling_.outSpatial;
        int outRem = outRow - nIdx * tiling_.outSpatial;
        int od = outRem / (tiling_.OH * tiling_.OW);
        int odRem = outRem - od * (tiling_.OH * tiling_.OW);
        int oh = odRem / tiling_.OW;
        int ow = odRem - oh * tiling_.OW;

        for (int cBase = 0; cBase < tiling_.C; cBase += vecLen_) {
            int remain = tiling_.C - cBase;
            int cLen = remain < vecLen_ ? remain : vecLen_;
            ProcessCTile(outRow, cBase, cLen, nIdx, od, oh, ow);
        }
    }

private:
    AvgPool3dTiling tiling_{};
    AscendC::TPipe *pipe_{nullptr};
    int vecLen_{DEFAULT_VEC_LEN};

    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castInBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castOutBuf_;

    AscendC::LocalTensor<dataType> inLocal_;
    AscendC::LocalTensor<dataType> outLocal_;
    AscendC::LocalTensor<float> inFloatLocal_;
    AscendC::LocalTensor<float> outFloatLocal_;
    AscendC::LocalTensor<float> accLocal_;
};

// =========================================================================
// Kernel entry point — dtype dispatch: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void avg_pool3d(
    GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM,
    int64_t dtypeFlag)
{
    AscendC::TPipe pipe;
    if (dtypeFlag == 0) {
        AvgPool3dKernel<float> kernel;
        kernel.Init(x, y, tilingGM, &pipe);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        AvgPool3dKernel<half> kernel;
        kernel.Init(x, y, tilingGM, &pipe);
        kernel.Process();
    } else {
        AvgPool3dKernel<bfloat16_t> kernel;
        kernel.Init(x, y, tilingGM, &pipe);
        kernel.Process();
    }
}
