// AvgPool3d op_host — tiling calculation + EXEC_KERNEL_CMD launch
// Input:  self [N, C, D, H, W] or [N, C, D, H, W] (5D)
// Layout transform: NCDHW → NDHWC → (N*D*H*W, C) flat for kernel

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_avg_pool3d.h"

constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
constexpr int32_t DEFAULT_VEC_LEN = 256;

namespace {

struct AvgPool3dTiling {
    int32_t N;           int32_t C;
    int32_t D;           int32_t H;           int32_t W;
    int32_t OD;          int32_t OH;          int32_t OW;
    int32_t kD;          int32_t kH;          int32_t kW;
    int32_t sD;          int32_t sH;          int32_t sW;
    int32_t pD;          int32_t pH;          int32_t pW;
    int32_t countIncludePad;
    int32_t divisorOverride;
    int32_t inSpatial;
    int32_t outSpatial;
    int32_t hw;
    int32_t vecLen;
    int32_t launchBlocks;
    int32_t reserved[8];
};

int64_t CeilDiv(int64_t value, int64_t factor)
{
    if (factor == 0) { return 0; }
    if (value % factor == 0) { return value / factor; }
    return value / factor + 1;
}

int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

void PopulateTiling(
    AvgPool3dTiling *tiling,
    int32_t n, int32_t c, int32_t d, int32_t h, int32_t w,
    int32_t od, int32_t oh, int32_t ow,
    int32_t kd, int32_t kh, int32_t kw,
    int32_t sd, int32_t sh, int32_t sw,
    int32_t pd, int32_t ph, int32_t pw,
    int32_t cip, int32_t divOverride, int32_t vecLen)
{
    tiling->N = n;           tiling->C = c;
    tiling->D = d;           tiling->H = h;           tiling->W = w;
    tiling->OD = od;         tiling->OH = oh;         tiling->OW = ow;
    tiling->kD = kd;         tiling->kH = kh;         tiling->kW = kw;
    tiling->sD = sd;         tiling->sH = sh;         tiling->sW = sw;
    tiling->pD = pd;         tiling->pH = ph;         tiling->pW = pw;
    tiling->countIncludePad = cip;
    tiling->divisorOverride = divOverride;
    tiling->inSpatial = d * h * w;
    tiling->outSpatial = od * oh * ow;
    tiling->hw = h * w;
    tiling->vecLen = vecLen;
    tiling->launchBlocks = 0;
    for (int i = 0; i < 8; ++i) { tiling->reserved[i] = 0; }
}

} // namespace

namespace ascend_kernel {

at::Tensor avg_pool3d(const at::Tensor &self, at::IntArrayRef kernel_size,
                       at::IntArrayRef stride, at::IntArrayRef padding,
                       bool ceil_mode, bool count_include_pad,
                       c10::optional<int64_t> divisor_override)
{
    TORCH_CHECK(self.dim() == 5, "avg_pool3d: input must be 5D (N, C, D, H, W)");
    TORCH_CHECK(!kernel_size.empty(), "avg_pool3d: kernel_size must not be empty");

    int64_t N = self.size(0);
    int64_t C = self.size(1);
    int64_t D = self.size(2);
    int64_t H = self.size(3);
    int64_t W = self.size(4);

    // Normalize kernel_size → (kD, kH, kW)
    int64_t kD = kernel_size[0];
    int64_t kH = kernel_size.size() == 1 ? kD : kernel_size[1];
    int64_t kW = kernel_size.size() == 1 ? kD : kernel_size[2];

    // Normalize stride → (sD, sH, sW), default = kernel_size
    int64_t sD, sH, sW;
    if (stride.empty()) {
        sD = kD; sH = kH; sW = kW;
    } else {
        sD = stride[0];
        sH = stride.size() == 1 ? sD : stride[1];
        sW = stride.size() == 1 ? sD : stride[2];
    }
    TORCH_CHECK(sD != 0 && sH != 0 && sW != 0, "avg_pool3d: stride should not contain zero");

    // Normalize padding → (pD, pH, pW)
    int64_t pD = padding[0];
    int64_t pH = padding.size() == 1 ? pD : padding[1];
    int64_t pW = padding.size() == 1 ? pD : padding[2];

    // Compute output spatial dimensions
    int64_t OD, OH, OW;
    if (!ceil_mode) {
        OD = (D + 2 * pD - kD) / sD + 1;
        OH = (H + 2 * pH - kH) / sH + 1;
        OW = (W + 2 * pW - kW) / sW + 1;
    } else {
        OD = CeilDiv(D + 2 * pD - kD, sD) + 1;
        OH = CeilDiv(H + 2 * pH - kH, sH) + 1;
        OW = CeilDiv(W + 2 * pW - kW, sW) + 1;
        if ((OD - 1) * sD >= D + pD) { OD -= 1; }
        if ((OH - 1) * sH >= H + pH) { OH -= 1; }
        if ((OW - 1) * sW >= W + pW) { OW -= 1; }
    }

    int32_t n32 = static_cast<int32_t>(N);
    int32_t c32 = static_cast<int32_t>(C);
    int32_t d32 = static_cast<int32_t>(D);
    int32_t h32 = static_cast<int32_t>(H);
    int32_t w32 = static_cast<int32_t>(W);
    int32_t od32 = static_cast<int32_t>(OD);
    int32_t oh32 = static_cast<int32_t>(OH);
    int32_t ow32 = static_cast<int32_t>(OW);
    int32_t kd32 = static_cast<int32_t>(kD);
    int32_t kh32 = static_cast<int32_t>(kH);
    int32_t kw32 = static_cast<int32_t>(kW);
    int32_t sd32 = static_cast<int32_t>(sD);
    int32_t sh32 = static_cast<int32_t>(sH);
    int32_t sw32 = static_cast<int32_t>(sW);
    int32_t pd32 = static_cast<int32_t>(pD);
    int32_t ph32 = static_cast<int32_t>(pH);
    int32_t pw32 = static_cast<int32_t>(pW);
    int32_t cip32 = count_include_pad ? 1 : 0;
    int32_t divOverride32 = divisor_override.has_value() ?
        static_cast<int32_t>(divisor_override.value()) : 0;

    int32_t inSpatial = d32 * h32 * w32;
    int32_t outSpatial = od32 * oh32 * ow32;
    int32_t totalOutRows = n32 * outSpatial;

    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,
                                             std::max<int32_t>(1, totalOutRows));
    int32_t vecLen = std::min<int32_t>(c32, DEFAULT_VEC_LEN);

    // Layout transform: NCDHW → NDHWC → (N*D*H*W, C)
    at::Tensor x_nhwc = self.permute({0, 2, 3, 4, 1}).contiguous();
    int64_t inTotal = N * D * H * W;
    at::Tensor x_flat = x_nhwc.reshape({inTotal, C});
    TORCH_CHECK(x_flat.is_contiguous(), "x_flat must be contiguous");

    // Allocate output (flattened NDHWC)
    int64_t outTotal = N * OD * OH * OW;
    at::Tensor y_flat = at::empty({outTotal, C}, x_flat.options());
    TORCH_CHECK(y_flat.is_contiguous(), "y_flat must be contiguous");

    // Prepare tiling data on device
    AvgPool3dTiling tilingHost;
    PopulateTiling(&tilingHost, n32, c32, d32, h32, w32, od32, oh32, ow32,
                   kd32, kh32, kw32, sd32, sh32, sw32, pd32, ph32, pw32,
                   cip32, divOverride32, vecLen);
    tilingHost.launchBlocks = usedCoreNum;

    at::Tensor tilingCpu = at::empty({static_cast<int64_t>(sizeof(AvgPool3dTiling))},
                                       at::device(at::kCPU).dtype(at::kByte));
    std::memcpy(tilingCpu.data_ptr(), &tilingHost, sizeof(AvgPool3dTiling));
    at::Tensor tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x_flat.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x_flat.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(avg_pool3d, blockDim,
                    x_flat, y_flat, tilingNpu, dtypeFlag);

    // Reshape output: (N*OD*OH*OW, C) → NDHWC → NCDHW
    at::Tensor y_ndhwc = y_flat.reshape({N, OD, OH, OW, C});
    at::Tensor y_ncdhw = y_ndhwc.permute({0, 4, 1, 2, 3}).contiguous();

    return y_ncdhw;
}

