23	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
24	{
25	    if (b == 0U) { return 0U; }
26	    return (a + b - 1U) / b;
27	}
28	
29	__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
30	{
31	    if (b == 0) { return 0; }
32	    return (a + b - 1) / b;
33	}
