38	struct AvgPool3dTiling {
39	    int32_t N;           int32_t C;
40	    int32_t D;           int32_t H;           int32_t W;
41	    int32_t OD;          int32_t OH;          int32_t OW;
42	    int32_t kD;          int32_t kH;          int32_t kW;
43	    int32_t sD;          int32_t sH;          int32_t sW;
44	    int32_t pD;          int32_t pH;          int32_t pW;
45	    int32_t countIncludePad;
