55	__aicore__ inline void CopyTiling(AvgPool3dTiling *tiling, GM_ADDR tilingGM)
56	{
57	    int32_t *dst = reinterpret_cast<int32_t *>(tiling);
58	    auto *src = reinterpret_cast<__gm__ int32_t *>(tilingGM);
59	    constexpr size_t count = sizeof(AvgPool3dTiling) / sizeof(int32_t);
60	    for (size_t i = 0; i < count; ++i) {
61	        dst[i] = src[i];
62	    }
63	}
