68	template <typename dataType>
69	__aicore__ inline void PrepareInputF32(
70	    AscendC::LocalTensor<float> &dst,
71	    AscendC::LocalTensor<dataType> &src,
72	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
73	    int32_t count)
74	{
75	    if constexpr (std::is_same_v<dataType, float>) {
76	        dst = src.template ReinterpretCast<float>();
77	        AscendC::PipeBarrier<PIPE_ALL>();
78	    } else {
79	        dst = castBuf.Get<float>();
80	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
81	        AscendC::PipeBarrier<PIPE_V>();
82	    }
83	}
