107	// AvgPool3d Kernel
108	// ---------------------------------------------------------------------------
109	template <typename dataType>
110	class AvgPool3dKernel {
111	public:
112	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM,
113	                                 AscendC::TPipe *pipe)
114	    {
115	        CopyTiling(&tiling_, tilingGM);
116	        if (tiling_.vecLen <= 0) { tiling_.vecLen = DEFAULT_VEC_LEN; }
117	        if (tiling_.vecLen > tiling_.C) { tiling_.vecLen = tiling_.C; }
118	
119	        uint64_t inElemNum = static_cast<uint64_t>(tiling_.N) * tiling_.inSpatial * tiling_.C;
120	        uint64_t outElemNum = static_cast<uint64_t>(tiling_.N) * tiling_.outSpatial * tiling_.C;
121	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), inElemNum);
122	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), outElemNum);
123	
124	        if ASCEND_IS_AIV {
125	            pipe_ = pipe;
126	            vecLen_ = tiling_.vecLen;
127	            pipe_->InitBuffer(inQueue_, BUFFER_NUM, static_cast<uint32_t>(vecLen_ * sizeof(dataType)));
128	            pipe_->InitBuffer(outQueue_, BUFFER_NUM, static_cast<uint32_t>(vecLen_ * sizeof(dataType)));
129	            pipe_->InitBuffer(accBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
130	            if constexpr (!std::is_same_v<dataType, float>) {
131	                pipe_->InitBuffer(castInBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
132	                pipe_->InitBuffer(castOutBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
133	            }
134	        }
135	    }
136	
137	    __aicore__ inline void Process()
138	    {
139	        if ASCEND_IS_AIV {
140	            int workerId = static_cast<int>(AscendC::GetBlockIdx());
141	            int workerCount = tiling_.launchBlocks;
142	            if (workerCount <= 0) { workerCount = 1; }
143	            int totalRows = tiling_.N * tiling_.outSpatial;
144	
145	            for (int outRow = workerId; outRow < totalRows; outRow += workerCount) {
146	                ProcessOneRow(outRow);
147	            }
148	        }
149	    }
150	
151	private:
152	    __aicore__ inline int ComputeDivisor(int od, int oh, int ow) const
153	    {
154	        if (tiling_.divisorOverride > 0) {
155	            return tiling_.divisorOverride;
156	        }
157	        if (tiling_.countIncludePad > 0) {
158	            return tiling_.kD * tiling_.kH * tiling_.kW;
159	        }
160	        int dStart = od * tiling_.sD - tiling_.pD;
161	        int hStart = oh * tiling_.sH - tiling_.pH;
162	        int wStart = ow * tiling_.sW - tiling_.pW;
163	        int dBegin = dStart < 0 ? 0 : dStart;
164	        int hBegin = hStart < 0 ? 0 : hStart;
165	        int wBegin = wStart < 0 ? 0 : wStart;
166	        int dEnd = dStart + tiling_.kD > tiling_.D ? tiling_.D : dStart + tiling_.kD;
167	        int hEnd = hStart + tiling_.kH > tiling_.H ? tiling_.H : hStart + tiling_.kH;
168	        int wEnd = wStart + tiling_.kW > tiling_.W ? tiling_.W : wStart + tiling_.kW;
169	        int validD = dEnd > dBegin ? (dEnd - dBegin) : 0;
170	        int validH = hEnd > hBegin ? (hEnd - hBegin) : 0;
171	        int validW = wEnd > wBegin ? (wEnd - wBegin) : 0;
172	        return validD * validH * validW;
173	    }
174	
175	    __aicore__ inline void ProcessCTile(int outRow, int cBase, int cLen,
176	                                         int nIdx, int od, int oh, int ow)
177	    {
178	        // Accumulate input over kernel window
179	        accLocal_ = accBuf_.Get<float>();
180	        AscendC::Duplicate(accLocal_, 0.0f, cLen);
181	
182	        for (int kd = 0; kd < tiling_.kD; ++kd) {
183	            int idVal = od * tiling_.sD - tiling_.pD + kd;
184	            if (idVal < 0 || idVal >= tiling_.D) { continue; }
185	            for (int kh = 0; kh < tiling_.kH; ++kh) {
186	                int ihVal = oh * tiling_.sH - tiling_.pH + kh;
187	                if (ihVal < 0 || ihVal >= tiling_.H) { continue; }
188	                for (int kw = 0; kw < tiling_.kW; ++kw) {
189	                    int iwVal = ow * tiling_.sW - tiling_.pW + kw;
190	                    if (iwVal < 0 || iwVal >= tiling_.W) { continue; }
191	                    int inRow = nIdx * tiling_.inSpatial + idVal * tiling_.hw +
192	                                ihVal * tiling_.W + iwVal;
193	
194	                    // CopyIn: load input slice
195	                    inLocal_ = inQueue_.AllocTensor<dataType>();
196	                    AscendC::DataCopy(inLocal_,
197	                        xGM_[static_cast<uint64_t>(inRow) * tiling_.C + cBase],
198	                        cLen);
199	                    inQueue_.EnQue(inLocal_);
200	
201	                    // DeQue and accumulate
202	                    inLocal_ = inQueue_.DeQue<dataType>();
203	                    PrepareInputF32<dataType>(inFloatLocal_, inLocal_, castInBuf_, cLen);
204	                    AscendC::Add(accLocal_, accLocal_, inFloatLocal_, cLen);
205	                    inQueue_.FreeTensor(inLocal_);
206	                }
207	            }
208	        }
209	
210	        // Compute output: acc / divisor
211	        int divisor = ComputeDivisor(od, oh, ow);
212	        outLocal_ = outQueue_.AllocTensor<dataType>();
213	
214	        if (divisor <= 0) {
215	            // Zero out if divisor is 0
216	            if constexpr (std::is_same_v<dataType, float>) {
217	                outFloatLocal_ = outLocal_.template ReinterpretCast<float>();
218	                AscendC::Duplicate(outFloatLocal_, 0.0f, cLen);
219	                AscendC::PipeBarrier<PIPE_V>();
220	            } else {
221	                outFloatLocal_ = castOutBuf_.Get<float>();
222	                AscendC::Duplicate(outFloatLocal_, 0.0f, cLen);
223	                CastBack<dataType>(outLocal_, outFloatLocal_, cLen);
224	            }
225	        } else {
226	            float invDiv = 1.0f / static_cast<float>(divisor);
227	            if constexpr (std::is_same_v<dataType, float>) {
228	                outFloatLocal_ = outLocal_.template ReinterpretCast<float>();
229	                AscendC::Muls(outFloatLocal_, accLocal_, invDiv, cLen);
230	                AscendC::PipeBarrier<PIPE_V>();
231	            } else {
232	                outFloatLocal_ = castOutBuf_.Get<float>();
233	                AscendC::Muls(outFloatLocal_, accLocal_, invDiv, cLen);
234	                CastBack<dataType>(outLocal_, outFloatLocal_, cLen);
235	            }
236	        }
237	
238	        outQueue_.EnQue(outLocal_);
239	
240	        // CopyOut
241	        outLocal_ = outQueue_.DeQue<dataType>();
242	        AscendC::DataCopy(yGM_[static_cast<uint64_t>(outRow) * tiling_.C + cBase],
243	                          outLocal_, cLen);
244	        outQueue_.FreeTensor(outLocal_);
245	    }
246	
247	    __aicore__ inline void ProcessOneRow(int outRow)
248	    {
249	        int nIdx = outRow / tiling_.outSpatial;
250	        int outRem = outRow - nIdx * tiling_.outSpatial;
251	        int od = outRem / (tiling_.OH * tiling_.OW);
252	        int odRem = outRem - od * (tiling_.OH * tiling_.OW);
253	        int oh = odRem / tiling_.OW;
254	        int ow = odRem - oh * tiling_.OW;
255	
256	        for (int cBase = 0; cBase < tiling_.C; cBase += vecLen_) {
257	            int remain = tiling_.C - cBase;
258	            int cLen = remain < vecLen_ ? remain : vecLen_;
259	            ProcessCTile(outRow, cBase, cLen, nIdx, od, oh, ow);
260	        }
261	    }
