264	    AvgPool3dTiling tiling_{};
265	    AscendC::TPipe *pipe_{nullptr};
266	    int vecLen_{DEFAULT_VEC_LEN};
267	
268	    AscendC::GlobalTensor<dataType> xGM_;
269	    AscendC::GlobalTensor<dataType> yGM_;
270	
271	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
272	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
